pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner1, address newOwner2) public {
        vm.assume(newOwner1 != address(0));
        vm.assume(newOwner2 != address(0));
        vm.assume(newOwner1 != newOwner2);
        address admin = address(uint160(uint256(keccak256(abi.encode("admin")))));
        vm.assume(newOwner1 != admin);
        vm.assume(newOwner2 != admin);

        // Step 1: admin sets owner to newOwner1
        vm.prank(admin);
        c.setOwner(newOwner1);

        // Step 2: newOwner1 tries to set owner to newOwner2
        vm.prank(newOwner1);
        c.setOwner(newOwner2);

        // In the reference contract, the second call reverts because newOwner1 is not admin.
        // So the owner should remain newOwner1.
        // In the buggy contract, the second call succeeds because onlyOwner accepts msg.sender == owner.
        // So the owner becomes newOwner2.
        // The assertion checks that the owner is still newOwner1.
        assertTrue(c.owner() == newOwner1);
    }
}

