pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Restrict to admissible domain: admin (deployer) is a special actor, exclude it to target non-admin calls
        vm.assume(caller != address(this));
        // Record original owner before any call
        address originalOwner = c.owner();
        // Make the potentially non-admin call
        vm.prank(caller);
        bool ok = true;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        // If the call reverted, owner must stay unchanged; if it succeeded (bug), the assertion will fail when the original owner equals originalOwner
        // but the reference requires that it never changes, so we assert that owner remains originalOwner.
        // In the bug, a non-admin owner can change owner, so owner may become newOwner, breaking the assertion.
        assertTrue(c.owner() == originalOwner);
    }
}

